function pendingCloudDeletes(){try{return JSON.parse(localStorage.getItem(PENDING_DELETE_KEY)||'[]')}catch{return[]}}
function queueCloudDelete(collection,ids){const cur=pendingCloudDeletes(),map=new Map(cur.map(x=>[`${x.collection}:${x.id}`,x]));(ids||[]).forEach(id=>map.set(`${collection}:${id}`,{collection,id}));localStorage.setItem(PENDING_DELETE_KEY,JSON.stringify([...map.values()].slice(-500)))}
