async function persistState(){const snap=rawSnapshot();await writeSnapshot(snap);return snap}
async function cloudWrite(ops,{silent=false}={}){
  const valid=(ops||[]).filter(x=>x?.collection&&x?.row?.id!==undefined);
  if(!valid.length)return true;
  if(!window.rndCloud?.enabled){queueCloudOps(valid);if(!silent)setCloudRuntimeStatus('offline','Saved locally · waiting for Firebase reconnect');return false}
  try{await window.rndCloud.writeMany(valid);setCloudRuntimeStatus('live');return true}catch(e){queueCloudOps(valid);console.error('Firebase write failed',e);setCloudRuntimeStatus('offline',e?.message||String(e));if(!silent)toast('Saved locally. Firebase will retry when cloud reconnects.',true);return false}
}
async function cloudDelete(collection,ids){const clean=[...new Set((ids||[]).map(Number).filter(Number.isFinite))];if(!clean.length)return true;if(!window.rndCloud?.enabled){queueCloudDelete(collection,clean);setCloudRuntimeStatus('offline','Delete saved locally · waiting for Firebase reconnect');return false}try{await window.rndCloud.deleteMany(collection,clean);setCloudRuntimeStatus('live');return true}catch(e){queueCloudDelete(collection,clean);setCloudRuntimeStatus('offline',e?.message||String(e));toast('Deleted locally. Firebase delete will retry when cloud reconnects.',true);return false}}
async function flushPendingCloudOps(){if(!window.rndCloud?.enabled)return true;try{const ops=pendingCloudOps();if(ops.length){await window.rndCloud.writeMany(ops);clearPendingCloudOps()}const dels=pendingCloudDeletes();if(dels.length){const by={};dels.forEach(x=>(by[x.collection]??=[]).push(x.id));for(const [collection,ids] of Object.entries(by))await window.rndCloud.deleteMany(collection,ids);clearPendingCloudDeletes()}setCloudRuntimeStatus('live');return true}catch(e){setCloudRuntimeStatus('offline',e?.message||String(e));return false}}

