function renderIdeas(){const q=$('#ideaSearch').value.toLowerCase().trim(), person=Number($('#ideaPersonFilter').value)||0, dep=Number($('#ideaDeptFilter').value)||0, date=$('#ideaDateFilter').value;const rows=state.ideas.filter(i=>(!q||[i.problem,i.proposed_idea,i.department_name,i.submitted_by_name,i.idea_number].join(' ').toLowerCase().includes(q))&&(!person||i.submitted_by===person)&&(!dep||i.department_id===dep)&&(!date||i.submission_date===date));$('#ideasTable').innerHTML=rows.length?rows.map(i=>`<tr><td>${fmtDate(i.submission_date)}</td><td><b>${esc(i.idea_number)}</b>${i.attachment_path?`<div class="sub"><a class="link" href="${i.attachment_path}" target="_blank">Attachment ↗</a></div>`:''}</td><td>${esc(i.submitted_by_name)}</td><td>${esc(i.department_name)}</td><td>${esc(i.problem)}</td><td>${esc(i.proposed_idea)}</td><td><span class="tag ${i.priority.toLowerCase()}">${esc(i.priority)}</span></td><td><span class="tag ${i.status}">${esc(i.status)}</span></td><td>${isVisitor()?'—':`<div class="row-actions"><button class="mini-action" data-edit-idea="${i.id}" title="Edit idea">Edit</button><button class="mini-action danger" data-delete-idea="${i.id}" title="Delete idea">×</button></div>`}</td></tr>`).join(''):'<tr><td colspan="9" class="empty-state">No ideas match the selected filters.</td></tr>'}
function renderWeekly(){const sel=Number($('#weekSelect').value)||state.cycles[0]?.id;if(sel)$('#weekSelect').value=sel;const c=state.cycles.find(x=>x.id===sel);if(!c){$('#weeklySetup').innerHTML='<div class="empty-state">Create a working week to begin shortlisting.</div>';return}const assigned=state.projects.filter(p=>p.cycle_id===c.id);if(assigned.length){$('#weeklySetup').innerHTML=`<div class="panel"><div class="panel-head"><div><span class="kicker">LOCKED WEEKLY ASSIGNMENT</span><h3>${esc(c.label)}</h3></div><div class="panel-actions"><span class="tag ${c.status}">${esc(c.status)}</span>${isVisitor()?'':`<button class="mini-action" data-edit-cycle="${c.id}">Edit</button><button class="mini-action danger" data-delete-cycle="${c.id}">×</button>`}</div></div>${assigned.map((p,i)=>`<div class="focus-project"><div class="focus-title"><span>0${i+1} · ${esc(p.title)}</span><span>${p.progress}%</span></div><div class="muted" style="font-size:12px;margin:5px 0">Owner: ${esc(p.owner_name||'—')} · ${fmtDate(p.start_date)} → ${fmtDate(p.end_date)}</div><div class="progress-track"><div class="progress-fill" style="width:${p.progress}%"></div></div></div>`).join('')}</div>`;return}const candidates=state.ideas.filter(i=>i.status==='submitted'&&i.submission_date>=c.start_date&&i.submission_date<=c.end_date);if(isVisitor()){$('#weeklySetup').innerHTML=`<section class="panel"><div class="panel-head"><div><span class="kicker">VIEW ONLY</span><h3>${esc(c.label)} · Available Ideas</h3></div><span class="tag visitor">ADMIN · VISITOR</span></div><div class="visitor-readonly">This account can review weekly ideas and assignments but cannot shortlist or create tasks.</div>${candidates.length?candidates.map(i=>`<div class="idea-choice"><div></div><div><b>${esc(i.proposed_idea)}</b><div class="muted" style="font-size:11px;margin-top:4px">${esc(i.idea_number)} · ${esc(i.submitted_by_name)} · ${esc(i.department_name)}</div><div style="font-size:12px;margin-top:6px">${esc(i.problem)}</div></div></div>`).join(''):'<div class="empty-state">No unassigned ideas available.</div>'}</section>`;return}$('#weeklySetup').innerHTML=`<div class="shortlist-grid"><section class="panel"><div class="panel-head"><div><span class="kicker">UNASSIGNED IDEAS</span><h3>Select 2 Ideas</h3></div><div class="panel-actions"><button class="mini-action" data-edit-cycle="${c.id}">Edit</button><button class="mini-action danger" data-delete-cycle="${c.id}">×</button></div></div><div id="candidateIdeas">${candidates.length?candidates.map(i=>`<label class="idea-choice"><input type="checkbox" class="ideaPick" value="${i.id}"><div><b>${esc(i.proposed_idea)}</b><div class="muted" style="font-size:11px;margin-top:4px">${esc(i.idea_number)} · ${esc(i.submitted_by_name)} · ${esc(i.department_name)}</div><div style="font-size:12px;margin-top:6px">${esc(i.problem)}</div></div></label>`).join(''):'<div class="empty-state">No unassigned ideas available. Submit ideas first.</div>'}</div></section><aside class="counter-box"><span class="kicker" style="color:#9eaaa3">WEEKLY RULE</span><div class="counter-num"><span id="pickCount">0</span> / 2</div><p>Exactly two ideas are required. Once assigned, they become this week's execution projects.</p><div id="ownerPickers"></div><button class="secondary-btn" id="assignWeekBtn" style="width:100%;margin-top:14px" disabled>Create Weekly Assignment</button></aside></div>`;bindWeeklyPicks()}
function bindWeeklyPicks(){$$('.ideaPick').forEach(cb=>cb.addEventListener('change',()=>{const picks=$$('.ideaPick:checked');if(picks.length>2){cb.checked=false;toast('Only 2 ideas can be selected.',true)}const now=$$('.ideaPick:checked');$$('.idea-choice').forEach(x=>x.classList.toggle('selected',x.querySelector('input').checked));$('#pickCount').textContent=now.length;$('#assignWeekBtn').disabled=now.length!==2;$('#ownerPickers').innerHTML=now.map((x,i)=>{const idea=state.ideas.find(a=>a.id===Number(x.value));return `<div class="owner-row"><span style="font-size:12px">0${i+1} ${esc(idea.proposed_idea.slice(0,42))}</span><select class="ownerSelect">${workingMembers().map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</select></div>`}).join('')}));$('#assignWeekBtn')?.addEventListener('click',assignWeek)}
async function assignWeek(){try{const ids=$$('.ideaPick:checked').map(x=>Number(x.value));if(ids.length!==2)return;const owners=$$('.ownerSelect').map(x=>Number(x.value));await assignWeekLocal(Number($('#weekSelect').value),ids,owners);toast('Two weekly projects assigned.');await load()}catch(e){toast(e.message,true)}}
function renderProjects(){const list=$('#projectList');if(!state.projects.length){list.innerHTML='<div class="empty-state">No weekly projects yet.</div>';$('#projectDetail').innerHTML='Select a weekly project to view its execution history.';return}if(!state.selectedProject||!state.projects.some(p=>p.id===state.selectedProject))state.selectedProject=state.projects[0].id;list.innerHTML=state.projects.map(p=>`<button class="project-list-item ${p.id===state.selectedProject?'active':''}" data-project="${p.id}"><b>${esc(p.project_number)}</b><small>${esc(p.cycle_label)}</small><div>${esc(p.title)}</div><div class="progress-track"><div class="progress-fill" style="width:${p.progress}%"></div></div></button>`).join('');$$('[data-project]').forEach(b=>b.onclick=()=>{state.selectedProject=Number(b.dataset.project);renderProjects()});renderProjectDetail()}
function renderProjectDetail(){const p=state.projects.find(x=>x.id===state.selectedProject);if(!p)return;const ups=state.progress.filter(x=>x.project_id===p.id).sort((a,b)=>b.update_date.localeCompare(a.update_date)||b.id-a.id);const stages=[20,40,60,80,100];$('#projectDetail').innerHTML=`<div class="project-hero"><div><span class="kicker">${esc(p.project_number)} · ${esc(p.cycle_label)}</span><h2>${esc(p.title)}</h2><p class="muted">${esc(p.department_name)} · Owner ${esc(p.owner_name||'—')} · ${fmtDate(p.start_date)} → ${fmtDate(p.end_date)}</p>${isVisitor()?'':`<div class="project-actions"><button class="primary-btn" id="openProgressBtn">+ DAILY PROGRESS UPDATE</button><button class="mini-action" id="editProjectBtn">Edit Project</button><button class="mini-action danger" id="deleteProjectBtn">× Delete</button></div>`}</div><div class="big-progress" style="--p:${p.progress*3.6}deg"><strong>${p.progress}%</strong></div></div><div class="milestone-rail">${['Problem','Analysis','Design','Trial','Complete'].map((s,i)=>`<div class="milestone ${p.progress>=stages[i]?'done':''}">${s}</div>`).join('')}</div><div class="panel-head"><div><span class="kicker">AUDITABLE HISTORY</span><h3>Progress Timeline</h3></div></div><div class="timeline">${ups.length?ups.map(u=>`<div class="timeline-item"><div class="timeline-date">${fmtDate(u.update_date)}</div><div class="timeline-pin"></div><div class="timeline-content"><h4>${esc(u.user_name)} · ${u.progress_percent}%</h4><p><b>Work:</b> ${esc(u.work_done)}</p>${u.remarks?`<p><b>Remarks:</b> ${esc(u.remarks)}</p>`:''}${u.blocker?`<p><b>Blocker:</b> ${esc(u.blocker)}</p>`:''}${u.next_action?`<p><b>Next:</b> ${esc(u.next_action)}</p>`:''}${u.attachment_path?`<a class="link" href="${u.attachment_path}" target="_blank">Open attachment ↗</a>`:''}${isVisitor()?'':`<div class="row-actions timeline-actions"><button class="mini-action" data-edit-progress="${u.id}">Edit</button><button class="mini-action danger" data-delete-progress="${u.id}">×</button></div>`}</div></div>`).join(''):'<div class="empty-state">No progress update entered yet.</div>'}</div>`;if($('#openProgressBtn'))$('#openProgressBtn').onclick=()=>openProgress(p);bindRecordActions()}
function renderSettings(){
  const visitor=isVisitor();
  const activeMembers=state.members.filter(m=>Number(m.active)!==0).sort((a,b)=>(a.sort_order||0)-(b.sort_order||0));
  const memberCount=activeMembers.filter(m=>m.role!=='visitor').length,visitorCount=activeMembers.filter(m=>m.role==='visitor').length;
  $('#membersSettings').innerHTML=`<div class="roster-summary"><div><strong>${memberCount}</strong><span>R&D Members</span></div><div><strong>${visitorCount}</strong><span>Visitors</span></div></div>${visitor?'':`<form class="member-add-form" id="addMemberForm"><label><span>Name</span><input id="newMemberName" maxlength="80" placeholder="Enter member name" required spellcheck="false" data-gramm="false" data-gramm_editor="false" data-enable-grammarly="false" autocorrect="off" autocapitalize="off"></label><label><span>Access</span><select id="newMemberRole"><option value="member">R&D Member</option><option value="visitor">Admin / Visitor</option></select></label><button class="primary-btn" type="submit">+ Add Login</button></form>`}<div class="roster-list">${activeMembers.length?activeMembers.map((m,i)=>`<div class="roster-slot ${m.role==='visitor'?'visitor-slot':''}"><div class="roster-index">${String(i+1).padStart(2,'0')}</div><div class="roster-edit"><label>LOGIN NAME</label>${visitor?`<strong>${esc(m.name)}</strong>`:`<input type="text" value="${esc(m.name)}" maxlength="80" data-member-name="${m.id}" spellcheck="false" data-gramm="false" data-gramm_editor="false" data-enable-grammarly="false" autocorrect="off" autocapitalize="off">`}</div>${visitor?`<span class="tag ${m.role==='visitor'?'visitor':'member'}">${m.role==='visitor'?'VISITOR':'MEMBER'}</span>`:`<select class="role-select" data-member-role="${m.id}"><option value="member" ${m.role!=='visitor'?'selected':''}>R&D Member</option><option value="visitor" ${m.role==='visitor'?'selected':''}>Visitor</option></select><div class="member-row-actions"><button class="secondary-btn roster-save" type="button" data-save-member="${m.id}">Save</button><button class="danger-outline-btn" type="button" data-delete-member="${m.id}" title="Delete login">×</button></div>`}</div>`).join(''):'<div class="empty-state">No active logins. Add a member to continue.</div>'}</div><p class="storage-note roster-note">Names are unique. Delete removes the login from active access but keeps its ID in the database so old ideas, assignments and progress remain correctly linked. Adding the same name later restores that same login instead of creating a duplicate.</p>`;
  $('#departmentsSettings').innerHTML=`<div class="dept-fixed-grid">${state.departments.map((d,i)=>`<div class="dept-fixed"><b>${String(i+1).padStart(2,'0')}</b><span>${esc(d.name)}</span><em>LOCKED</em></div>`).join('')}</div>`;
  const cm=currentMember();if(cm){$('#settingsSignedInName').textContent=cm.name;$('#signedInName').textContent=cm.name;const settingsRole=$('#settingsSignedInRole');if(settingsRole){settingsRole.textContent=cm.role==='visitor'?'ADMIN · VISITOR':'R&D MEMBER';settingsRole.className='tag '+(cm.role==='visitor'?'visitor':'member')}}
  const ss=$('#storageStatus');if(ss)ss.textContent=storageStatus();
  const dbs=$('#databaseStats');if(dbs){const dates=[...state.ideas.map(i=>i.submission_date),...state.progress.map(p=>p.update_date)].filter(Boolean).sort();dbs.innerHTML=`<div><span>Ideas</span><strong>${state.ideas.length}</strong></div><div><span>Weekly projects</span><strong>${state.projects.length}</strong></div><div><span>Progress entries</span><strong>${state.progress.length}</strong></div><div><span>Active logins</span><strong>${activeMembers.length}</strong></div><div><span>Cloud</span><strong>${cloudRuntimeStatus==='live'?'Live':'Offline cache'}</strong></div><div><span>Stored history</span><strong>${dates.length?`${fmtDate(dates[0])} → ${fmtDate(dates.at(-1))}`:'No entries yet'}</strong></div>`}
  $$('[data-save-member]').forEach(btn=>btn.onclick=async()=>{const id=Number(btn.dataset.saveMember),input=$(`[data-member-name="${id}"]`),role=$(`[data-member-role="${id}"]`);try{btn.disabled=true;await updateMemberLocal(id,{name:input.value,role:role.value});toast('Login updated and saved to Firebase.')}catch(e){toast(e.message,true);renderSettings()}finally{btn.disabled=false}});
  $$('[data-delete-member]').forEach(btn=>btn.onclick=async()=>{const id=Number(btn.dataset.deleteMember),m=state.members.find(x=>Number(x.id)===id);if(!m)return;if(!confirm(`Delete ${m.name} from active logins? Historical records will be preserved.`))return;try{btn.disabled=true;await deleteMemberLocal(id);toast(`${m.name} removed from active logins.`)}catch(e){toast(e.message,true);renderSettings()}finally{btn.disabled=false}});
  const addForm=$('#addMemberForm');if(addForm)addForm.onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await addMemberLocal({name:$('#newMemberName').value,role:$('#newMemberRole').value});toast('New login added and saved to Firebase.')}catch(err){toast(err.message,true)}finally{b.disabled=false}};
  disableWritingAssist($('#settingsPage'));
}
function analyticsBars(items,maxValue,labelKey='label',valueKey='value',suffix=''){
  const max=Math.max(1,Number(maxValue)||Math.max(0,...items.map(x=>Number(x[valueKey]||0))));
  return `<div class="analytics-bars">${items.map(x=>{const v=Number(x[valueKey]||0),w=Math.round(v/max*100);return `<div class="analytics-bar-row"><div class="analytics-bar-meta"><span>${esc(x[labelKey])}</span><b>${v}${suffix}</b></div><div class="analytics-bar-track"><i style="width:${w}%"></i></div></div>`}).join('')}</div>`;
}
function renderReportControls(){const out=$('#reportControls');if(state.reportType==='daily'){out.innerHTML=`<div class="report-controls-line"><label>Date<input type="date" id="reportDate" value="${today()}"></label><button class="primary-btn" id="runReport">Generate</button><button class="ghost-btn" id="printReport">Print / Save PDF</button><button class="ghost-btn" id="excelReport">Download Excel</button></div>`}else{out.innerHTML=`<div class="report-controls-line"><label>Working Week<select id="reportWeek">${state.cycles.map(c=>`<option value="${c.id}">${esc(c.label)}</option>`).join('')}</select></label><button class="primary-btn" id="runReport">Generate</button><button class="ghost-btn" id="printReport">Print / Save PDF</button><button class="ghost-btn" id="excelReport">Download Excel</button></div>`}$('#runReport')?.addEventListener('click',generateReport);$('#printReport')?.addEventListener('click',()=>window.print());$('#excelReport')?.addEventListener('click',downloadExcel);generateReport()}
let currentReport={type:'daily',data:null};async function generateReport(){try{if(state.reportType==='daily'){const date=$('#reportDate')?.value||today(),d=dailyReportLocal(date);currentReport={type:'daily',data:d};const byMember=workingMembers().map(m=>({name:m.name,n:d.ideas.filter(i=>Number(i.submitted_by)===Number(m.id)).length}));$('#reportOutput').innerHTML=`<div class="report-header"><div><span class="kicker">R&D DAILY REPORT</span><h2>${fmtDate(d.date)}</h2></div><b>R&D TRACK</b></div><div class="report-kpis"><div class="report-kpi"><span class="kicker">IDEAS</span><strong>${d.ideas.length}</strong></div><div class="report-kpi"><span class="kicker">UPDATES</span><strong>${d.updates.length}</strong></div><div class="report-kpi"><span class="kicker">PEOPLE SUBMITTED</span><strong>${byMember.filter(x=>x.n).length}/${byMember.length}</strong></div><div class="report-kpi"><span class="kicker">BLOCKERS</span><strong>${d.updates.filter(x=>x.blocker).length}</strong></div></div><div class="analytics-report-grid"><section class="analytics-visual-card"><div class="visual-card-head"><span class="kicker">SUBMISSION DISTRIBUTION</span><b>By member</b></div>${analyticsBars(byMember,Math.max(1,...byMember.map(x=>x.n)),'name','n')}</section><section class="analytics-visual-card"><div class="visual-card-head"><span class="kicker">DAY HEALTH</span><b>${d.updates.filter(x=>x.blocker).length?'Attention needed':'On track'}</b></div><div class="health-ring" style="--score:${Math.round((byMember.filter(x=>x.n).length/Math.max(1,byMember.length))*100)}"><strong>${Math.round((byMember.filter(x=>x.n).length/Math.max(1,byMember.length))*100)}%</strong><span>submission coverage</span></div></section></div><h3>Idea Submission</h3><table class="mini-table"><thead><tr><th>Person</th><th>Ideas</th></tr></thead><tbody>${byMember.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.n}</td></tr>`).join('')}</tbody></table><h3>Project Progress Updates</h3><table class="mini-table"><thead><tr><th>Project</th><th>Person</th><th>Progress</th><th>Work Done</th></tr></thead><tbody>${d.updates.length?d.updates.map(u=>`<tr><td>${esc(u.project_number)}</td><td>${esc(u.user_name)}</td><td>${u.progress_percent}%</td><td>${esc(u.work_done)}</td></tr>`).join(''):'<tr><td colspan="4">No progress updates.</td></tr>'}</tbody></table>`}else{const id=Number($('#reportWeek')?.value||state.cycles[0]?.id);if(!id){$('#reportOutput').innerHTML='<div class="empty-state">Create a week first.</div>';return}const d=weeklyReportLocal(id);currentReport={type:'weekly',data:d};const avg=d.projects.length?Math.round(d.projects.reduce((a,p)=>a+p.progress,0)/d.projects.length):0;$('#reportOutput').innerHTML=`<div class="report-header"><div><span class="kicker">R&D WEEKLY REPORT</span><h2>${esc(d.cycle.label)}</h2><div class="muted">${fmtDate(d.cycle.start_date)} – ${fmtDate(d.cycle.end_date)}</div></div><b>R&D TRACK</b></div><div class="report-kpis"><div class="report-kpi"><span class="kicker">IDEAS SUBMITTED</span><strong>${d.ideas.length}</strong></div><div class="report-kpi"><span class="kicker">SHORTLISTED</span><strong>${d.projects.length}</strong></div><div class="report-kpi"><span class="kicker">COMPLETED</span><strong>${d.projects.filter(p=>p.progress===100).length}</strong></div><div class="report-kpi"><span class="kicker">AVG PROGRESS</span><strong>${avg}%</strong></div></div><div class="analytics-report-grid"><section class="analytics-visual-card"><div class="visual-card-head"><span class="kicker">PROJECT PROGRESS</span><b>${avg}% average</b></div>${analyticsBars(d.projects.map(p=>({label:p.title,value:p.progress})),100,'label','value','%')}</section><section class="analytics-visual-card"><div class="visual-card-head"><span class="kicker">WEEK HEALTH</span><b>${d.projects.filter(p=>p.progress===100).length}/${d.projects.length||0} completed</b></div><div class="health-ring" style="--score:${avg}"><strong>${avg}%</strong><span>overall execution</span></div></section></div><h3>Weekly Projects</h3><table class="mini-table"><thead><tr><th>Project</th><th>Owner</th><th>Progress</th><th>Status</th></tr></thead><tbody>${d.projects.map(p=>`<tr><td>${esc(p.project_number)} · ${esc(p.title)}</td><td>${esc(p.owner_name||'—')}</td><td>${p.progress}%</td><td>${esc(p.status)}</td></tr>`).join('')}</tbody></table><h3>Team Contribution</h3><table class="mini-table"><thead><tr><th>Member</th><th>Ideas</th><th>Progress Updates</th></tr></thead><tbody>${d.contribution.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.idea_count}</td><td>${x.update_count}</td></tr>`).join('')}</tbody></table>`}}catch(e){toast(e.message,true)}}
function downloadExcel(){if(!currentReport.data)return;const table=$('#reportOutput').innerHTML;const html=`<html><head><meta charset="utf-8"></head><body>${table}</body></html>`;const blob=new Blob([html],{type:'application/vnd.ms-excel'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`RND-${currentReport.type}-report.xls`;a.click();URL.revokeObjectURL(a.href)}
function openIdea(){delete $('#ideaForm').dataset.editId;$('#ideaDialogTitle').textContent='Submit Daily Idea';$('#ideaForm').reset();if(isVisitor()){toast('Admin visitors are view-only and do not submit ideas.',true);return}const d=$('#ideaDialog');$('#ideaMember').value=activeUser();$('#ideaDate').value=today();d.showModal()}
function openProgress(p){delete $('#progressForm').dataset.editId;$('#progressForm').reset();if(isVisitor()){toast('Admin visitors are view-only.',true);return}$('#progressDialogTitle').textContent=p.project_number+' — Daily Update';$('#progressMember').value=activeUser();$('#progressDate').value=today();$('#progressPercent').value=p.progress;$('#progressForm').dataset.projectId=p.id;$('#progressDialog').showModal()}
function applyRoleAccess(){const visitor=isVisitor();['#quickIdeaBtn','#newIdeaBtn','#newWeekBtn'].forEach(id=>{const el=$(id);if(el)el.classList.toggle('role-hidden',visitor)});const note=$('#visitorNotice');if(note)note.classList.toggle('hidden',!visitor);document.body.classList.toggle('visitor-mode',visitor)}
function bindRecordActions(){
  $$('[data-edit-idea]').forEach(b=>b.onclick=()=>openIdeaEdit(Number(b.dataset.editIdea)));$$('[data-delete-idea]').forEach(b=>b.onclick=async()=>{const i=state.ideas.find(x=>x.id===Number(b.dataset.deleteIdea));if(!i)return;const linked=state.projects.some(p=>p.idea_id===i.id);if(!confirm(`Delete ${i.idea_number}?${linked?' Linked project and progress history will also be removed.':''}`))return;await deleteIdeaLocal(i.id);toast('Idea deleted.')});
  $$('[data-edit-cycle]').forEach(b=>b.onclick=()=>openCycleEdit(Number(b.dataset.editCycle)));$$('[data-delete-cycle]').forEach(b=>b.onclick=async()=>{const c=state.cycles.find(x=>x.id===Number(b.dataset.deleteCycle));if(!c)return;if(!confirm(`Delete ${c.label}? Weekly projects and their progress will be removed; linked ideas return to Submitted.`))return;await deleteCycleLocal(c.id);toast('Week deleted.')});
  $$('[data-edit-progress]').forEach(b=>b.onclick=()=>openProgressEdit(Number(b.dataset.editProgress)));$$('[data-delete-progress]').forEach(b=>b.onclick=async()=>{if(!confirm('Delete this progress entry? Project progress will be recalculated.'))return;await deleteProgressLocal(Number(b.dataset.deleteProgress));toast('Progress entry deleted.')});
  const ep=$('#editProjectBtn');if(ep)ep.onclick=()=>openProjectEdit(state.selectedProject);const dp=$('#deleteProjectBtn');if(dp)dp.onclick=async()=>{const p=state.projects.find(x=>x.id===state.selectedProject);if(!p)return;if(!confirm(`Delete ${p.project_number}? Its progress history will be removed and the linked idea will return to Submitted.`))return;await deleteProjectLocal(p.id);state.selectedProject=null;toast('Project deleted.')};
}
function openIdeaEdit(id){const i=state.ideas.find(x=>x.id===id);if(!i)return;$('#ideaForm').dataset.editId=id;$('#ideaDialogTitle').textContent='Edit Daily Idea';$('#ideaMember').value=i.submitted_by;$('#ideaDepartment').value=i.department_id;$('#ideaProblem').value=i.problem;$('#ideaProposal').value=i.proposed_idea;$('#ideaBenefit').value=i.expected_benefit||'';$('#ideaPriority').value=i.priority;$('#ideaDate').value=i.submission_date;$('#ideaDialog').showModal()}
function openCycleEdit(id){const c=state.cycles.find(x=>x.id===id);if(!c)return;$('#weekForm').dataset.editId=id;$('#weekDialogTitle').textContent='Edit Working Week';$('#weekLabel').value=c.label;$('#weekStart').value=c.start_date;$('#weekEnd').value=c.end_date;$('#weekDialog').showModal()}
function openProgressEdit(id){const u=state.progress.find(x=>x.id===id);if(!u)return;const p=state.projects.find(x=>x.id===u.project_id);$('#progressForm').dataset.editId=id;$('#progressForm').dataset.projectId=u.project_id;$('#progressDialogTitle').textContent=(p?.project_number||'Project')+' — Edit Update';$('#progressMember').value=u.user_id;$('#progressDate').value=u.update_date;$('#progressPercent').value=u.progress_percent;$('#progressWork').value=u.work_done;$('#progressRemarks').value=u.remarks||'';$('#progressBlocker').value=u.blocker||'';$('#progressNext').value=u.next_action||'';$('#progressDialog').showModal()}
function openProjectEdit(id){const p=state.projects.find(x=>x.id===Number(id));if(!p)return;$('#projectEditId').value=p.id;$('#projectEditTitle').value=p.title;$('#projectEditOwner').innerHTML=workingMembers().map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('');$('#projectEditOwner').value=p.owner_id;$('#projectEditStart').value=p.start_date;$('#projectEditEnd').value=p.end_date;$('#projectEditDialog').showModal()}
function showPage(name){state.page=name;$$('.page').forEach(p=>p.classList.remove('active'));$(`#${name}Page`).classList.add('active');$$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.page===name));const titles={dashboard:'Dashboard',ideas:'Daily Ideas',weekly:'Weekly Tasks',progress:'Progress Tracker',reports:'Analytics',settings:'Settings'};$('#pageTitle').textContent=titles[name];$('#sidebar').classList.remove('open');if(name==='reports')renderReportControls()}
function bind(){
  $('#loginForm').onsubmit=async e=>{e.preventDefault();const name=$('#loginName').value.trim();$('#loginMessage').textContent='';$('#loginSuggestion').innerHTML='';try{const result=findLogin(name);if(result.matched){persistLogin(result.member);requestNotificationsFromGesture();$('#loginName').value='';showApp();toast(`Welcome, ${result.member.name}.`);return}$('#loginMessage').textContent=result.error||'Name not found.';if(result.suggestion){$('#loginSuggestion').innerHTML=`<div class="suggestion-box"><span>Did you mean <b>${esc(result.suggestion.name)}</b>?</span><button type="button" class="secondary-btn" id="useSuggestionBtn">Yes, use this name</button></div>`;$('#useSuggestionBtn').onclick=()=>{persistLogin(result.suggestion);requestNotificationsFromGesture();$('#loginName').value='';showApp();toast(`Welcome, ${result.suggestion.name}.`)}}}catch(err){$('#loginMessage').textContent=err.message}};
  $('#exportDbBtn').onclick=()=>{exportDatabase();toast('Database backup downloaded.');};
  $('#importDbInput').onchange=async e=>{try{await importDatabaseFile(e.target.files?.[0]);toast('Database restored successfully.');e.target.value='';await load()}catch(err){toast(err.message,true)}};
  $('#requestStorageBtn').onclick=async()=>{const ok=await requestDurableStorage();toast(ok?'Persistent browser storage enabled.':'Browser kept standard storage mode.',!ok);renderSettings()};;
  $('#logoutBtn').onclick=()=>{clearLogin();$('#loginMessage').textContent='';$('#loginSuggestion').innerHTML='';showLogin()};
  $$('.nav-btn').forEach(b=>b.onclick=()=>showPage(b.dataset.page));$$('[data-go]').forEach(b=>b.onclick=()=>showPage(b.dataset.go));$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');$('#quickIdeaBtn').onclick=()=>{requestNotificationsFromGesture();openIdea()};$('#newIdeaBtn').onclick=()=>{requestNotificationsFromGesture();openIdea()};$('#newWeekBtn').onclick=()=>{if(isVisitor())return toast('Admin visitors are view-only.',true);delete $('#weekForm').dataset.editId;$('#weekForm').reset();$('#weekDialogTitle').textContent='Create Working Week';$('#weekDialog').showModal()};$$('[data-close]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close).close());['#ideaSearch','#ideaPersonFilter','#ideaDeptFilter','#ideaDateFilter'].forEach(s=>$(s).addEventListener('input',renderIdeas));$('#clearIdeaFilters').onclick=()=>{$('#ideaSearch').value='';$('#ideaPersonFilter').value='';$('#ideaDeptFilter').value='';$('#ideaDateFilter').value='';renderIdeas()};$('#weekSelect').onchange=renderWeekly;$$('.report-tab').forEach(b=>b.onclick=()=>{$$('.report-tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.reportType=b.dataset.report;renderReportControls()});$('#ideaForm').onsubmit=async e=>{e.preventDefault();const submitBtn=e.submitter||e.target.querySelector('button[type="submit"],button:not([type])');if(submitBtn){submitBtn.disabled=true;submitBtn.textContent='SUBMITTING…'}try{const attachment=await fileData($('#ideaAttachment'));const payload={submitted_by:Number($('#ideaMember').value),department_id:Number($('#ideaDepartment').value),problem:$('#ideaProblem').value,proposed_idea:$('#ideaProposal').value,expected_benefit:$('#ideaBenefit').value,priority:$('#ideaPriority').value,submission_date:$('#ideaDate').value,attachment};const editId=Number(e.target.dataset.editId)||0;const row=editId?await updateIdeaLocal(editId,payload):await createIdeaLocal(payload);delete e.target.dataset.editId;$('#ideaDialog').close();e.target.reset();disableWritingAssist(e.target);renderAll();toast(editId?`${row.idea_number} updated.`:(row.cloud_saved?`${row.idea_number} saved to Firebase and dashboard updated.`:`${row.idea_number} saved locally · Firebase sync pending.`),!editId&&!row.cloud_saved)}catch(err){toast(err.message,true)}finally{if(submitBtn){submitBtn.disabled=false;submitBtn.textContent='Submit Idea'}}};$('#weekForm').onsubmit=async e=>{e.preventDefault();try{const payload={label:$('#weekLabel').value,start_date:$('#weekStart').value,end_date:$('#weekEnd').value};const editId=Number(e.target.dataset.editId)||0;if(editId)await updateCycleLocal(editId,payload);else await createCycleLocal(payload);delete e.target.dataset.editId;$('#weekDialog').close();e.target.reset();toast(editId?'Working week updated.':'Working week created.');await load()}catch(err){toast(err.message,true)}};$('#projectEditForm').onsubmit=async e=>{e.preventDefault();try{await updateProjectLocal(Number($('#projectEditId').value),{title:$('#projectEditTitle').value,owner_id:Number($('#projectEditOwner').value),start_date:$('#projectEditStart').value,end_date:$('#projectEditEnd').value});$('#projectEditDialog').close();toast('Project updated.')}catch(err){toast(err.message,true)}};$('#progressForm').onsubmit=async e=>{e.preventDefault();try{const attachment=await fileData($('#progressAttachment'));const payload={user_id:Number($('#progressMember').value),update_date:$('#progressDate').value,progress_percent:Number($('#progressPercent').value),work_done:$('#progressWork').value,remarks:$('#progressRemarks').value,blocker:$('#progressBlocker').value,next_action:$('#progressNext').value,attachment};const editId=Number(e.target.dataset.editId)||0;if(editId)await updateProgressLocal(editId,payload);else await addProgressLocal(Number(e.target.dataset.projectId),payload);delete e.target.dataset.editId;$('#progressDialog').close();e.target.reset();toast(editId?'Progress update edited.':'Progress update saved.');await load()}catch(err){toast(err.message,true)}}}
disableWritingAssist();new MutationObserver(m=>m.forEach(x=>x.addedNodes.forEach(n=>{if(n.nodeType===1)disableWritingAssist(n)}))).observe(document.documentElement,{childList:true,subtree:true});bind();load().catch(e=>{showLogin();$('#loginMessage').textContent=e.message});
